#!/usr/bin/env python3
"""Generate scenarios/cas_portrait.toml (the skater-photo regeneration check).

The scenario is a long run of menu presses; writing it out by hand repeated
the same blocks four times. Waits are in frames at the 30 fps cap: menu
moves need ~10-20 frames, a screen change ~30, entering Create-a-Skater ~120
(the CAS stage loads), and leaving it ~150 (skater photo + save + team
screen).

  python3 tools/harness/gen_cas_portrait.py > scenarios/cas_portrait.toml
"""

HEADER = """\
# GENERATED by tools/harness/gen_cas_portrait.py; edit that, not this.
# Skater photo (team portrait) regeneration: open Pause > Edit Skaters, then
# twice put a helmet on in Create-a-Skater and take it off again, leaving
# with "Yes" each time. Each exit saves the profile and regenerates the
# skater photo; the team screen's first box must show the current look:
#   cas_helmet_N -> helmet, cas_plain_N -> no hat (cas_pick_N / cas_off_N:
#   the skater in Create-a-Skater right after the change).
# Ends with the profile as it started (no hat), but it WRITES the save
# (Windows test profile, or the device's: ask first there).
#
#   run_scenario.py windows scenarios/cas_portrait.toml
#   ... -- --skate3_native_render_scene_portrait_scene_band=true   (old behavior)
name = "cas_portrait"
timeout_s = 600
boot = "demo"

[cvars]
skate3_demo_path_signed_in = true
skate3_guest_fps_cap = 30.0
skate3_guest_fps_cap_auto = false

[[step]]
do = "wait"
gameplay = true
timeout_s = 400

[[step]]
do = "wait"
frames = 150
"""

MENU = 15      # between moves inside one menu
SCREEN = 30    # after a press that opens or closes a screen
ENTER_CAS = 120
LEAVE_CAS = 150


def press(buttons=None, lx=None, ly=None, wait=MENU):
    s = "\n[[step]]\ndo = \"input\"\n"
    if buttons:
        s += f"buttons = \"{buttons}\"\n"
    if lx is not None:
        s += f"lx = {lx}\n"
    if ly is not None:
        s += f"ly = {ly}\n"
    s += "frames = 4\n"
    return s + f"\n[[step]]\ndo = \"wait\"\nframes = {wait}\n"


def shot(tag):
    return f"\n[[step]]\ndo = \"screenshot\"\ntag = \"{tag}\"\n"


def to_hats():
    # Edit Skater (team screen) -> Create-a-Skater -> Merchandise -> Hats.
    return (press("a", wait=ENTER_CAS) + press(ly=-1.0) + press("a", wait=SCREEN)
            + press("a", wait=SCREEN))


def leave_cas():
    # Back out to the "finished editing?" prompt, then Yes.
    return press("b", wait=SCREEN) + press("b", wait=SCREEN) + press("a", wait=LEAVE_CAS)


def helmet_on(n):
    out = f"\n# ---- cycle {n}: helmet on (third cell of the Hats grid)\n"
    out += to_hats() + press(lx=1.0) + press(lx=1.0) + press("a", wait=SCREEN)
    out += shot(f"cas_pick_{n}") + press("a", wait=SCREEN)  # Edit Clothing: accept
    return out + leave_cas() + shot(f"cas_helmet_{n}")


def helmet_off(n):
    out = f"\n# ---- cycle {n}: helmet off (the first Hats cell removes it)\n"
    out += to_hats() + press("a", wait=SCREEN) + shot(f"cas_off_{n}")
    return out + leave_cas() + shot(f"cas_plain_{n}")


def main():
    import argparse

    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--only", choices=["on", "off"],
                    help="one change and exit (the next boot's team_start shows the SAVED photo: "
                         "run 'on', then 'off' to check it and restore the profile)")
    args = ap.parse_args()
    out = HEADER
    if args.only:
        out = out.replace('name = "cas_portrait"', f'name = "cas_portrait_{args.only}"')
    out += "\n# Pause > Edit Skaters (second entry): the team screen, FE [0,56,63].\n"
    out += press("start", wait=SCREEN) + press(ly=-1.0) + press("a", wait=SCREEN + 15)
    out += shot("team_start")
    if args.only == "on":
        out += helmet_on(1)
    elif args.only == "off":
        out += helmet_off(1)
    else:
        for n in (1, 2):
            out += helmet_on(n) + helmet_off(n)
    print(out, end="")


if __name__ == "__main__":
    main()
